44: {
45:   SISLCurve *pc=NULL;
46:   double aepsco,aepsge,top[3],axispt[3],conept[3];
47:   double st[100],stcoef[100],*spar=NULL;
48:   int kstat;
49:   int cone_exists=0;
50:   int kk,kn,kdim,ki;
51:   int kpt,kcrv;
52:   SISLIntcurve **qrcrv=NULL;
53:   char ksvar[100];
54:   kdim=3;
55:   aepsge=0.001; /* geometric tolerance */
56:   aepsco=0.000001; /* computational tolerance This parameter is included from historical reasons
57:                       and no longer used  */
58: 
59:   ksvar[0] = '0';  /* arbitrary character */
60:   while (ksvar[0] != 'q')
61:     {
62:       printf("\n cu - define a new B-spline curve");
63:       printf("\n co - define a new cone");
64:       printf("\n i - intersect the B-spline curve with the cone");
65:       printf("\n q - quit");
66:       printf("\n> ");
67:       scanf("%s",ksvar);
68: 
69:       if (ksvar[0] == 'c' && ksvar[1] == 'u')
70: 	{
71: 	  printf("\n Give number of vertices, order of curve: ");
72: 	  scanf("%d %d", &kn, &kk);
73: 	  printf("Give knots values in ascending order: \n");
74: 	  for (ki=0;ki<kn+kk;ki++)
75: 	    {
76: 	      scanf("%lf",&st[ki]);
77: 	    }
78: 	  printf("Give vertices \n");
79: 	  for (ki=0;ki<kn*kdim;ki++)
80: 	    {
81: 	      scanf("%lf",&stcoef[ki]);
82: 	    }
83: 	  if(pc) freeCurve(pc);
84: 	  pc = newCurve(kn,kk,st,stcoef,1,kdim,1);
85: 	}
86:       else if (ksvar[0] == 'c' && ksvar[1] == 'o')
87: 	{
88: 	  printf("\n Give top point: ");
89: 	  scanf("%lf %lf %lf",&top[0],&top[1],&top[2]);
90: 	  printf("\n Give a point on the axis: ");
91: 	  scanf("%lf %lf %lf",&axispt[0],&axispt[1],&axispt[2]);
92: 	  printf("\n Give a point on the cone surface: ");
93: 	  scanf("%lf %lf %lf",&conept[0],&conept[1],&conept[2]);
94: 	  cone_exists=1;
95: 	}
96:       else if (ksvar[0] == 'i' && cone_exists && pc)
97: 	{
98: 	  s1373(pc,top,axispt,conept,kdim,aepsco,aepsge,
99: 		&kpt,&spar,&kcrv,&qrcrv,&kstat);
100: 	  printf("\n kstat %d",kstat);
101: 	  printf("\n kpt %d",kpt);
102: 	  printf("\n kcrv %d",kcrv);
103: 	  for (ki=0;ki<kpt;ki++)
104: 	    {
105: 	      printf("\nIntersection point %lf",spar[ki]);
106: 	    }
107: 	  if (spar)
108: 	    {
109: 	      free (spar);
